-- Sprint 46 - Ecossistema SaaS aberto, marketplace e integrações seguras
create table if not exists platform_marketplace_modules(id uuid primary key,code varchar(80) not null unique,name varchar(160) not null,description text not null,segments text[] not null default '{}',plans text[] not null default '{}',dependencies text[] not null default '{}',official boolean not null default false,featured boolean not null default false,status varchar(20) not null check(status in('DRAFT','ACTIVE','INACTIVE')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_tenant_modules(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),module_id uuid not null references platform_marketplace_modules(id),status varchar(20) not null check(status in('ACTIVE','INACTIVE','REJECTED','BLOCKED')),trial_started_at timestamptz,trial_ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,unique(tenant_id,module_id),check(trial_ends_at is null or trial_started_at is not null));
create table if not exists platform_marketplace_requests(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),module_id uuid not null references platform_marketplace_modules(id),status varchar(20) not null check(status in('PENDING','APPROVED','REJECTED','CANCELLED')),justification text,trial_ends_at timestamptz,decision_reason text,decided_at timestamptz,decided_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_partner_accounts(id uuid primary key,name varchar(200) not null,type varchar(40) not null check(type in('AGRO_CONSULTING','RESELLER','INTEGRATOR','ACCREDITED_TECHNICIAN','ACCOUNTING_TAX','LOGISTICS','LABORATORY','COOPERATIVE','EXTERNAL_DEVELOPER','GOVERNMENT_AGREEMENT','OTHER')),document varchar(14) not null unique,email varchar(254) not null,coverage text not null,segments text[] not null default '{}',status varchar(20) not null check(status in('ACTIVE','BLOCKED','INACTIVE')),blocked_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_partner_tenant_access(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),partner_id uuid not null references platform_partner_accounts(id),scopes text[] not null,modules text[] not null,status varchar(20) not null check(status in('ACTIVE','REVOKED','BLOCKED','EXPIRED')),expires_at timestamptz not null,revoked_at timestamptz,revocation_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_external_apps(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),name varchar(160) not null,description text not null,status varchar(20) not null check(status in('ACTIVE','SUSPENDED','REVOKED')),requests_per_minute int not null check(requests_per_minute between 1 and 10000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,unique(tenant_id,id));
create table if not exists platform_api_scopes(id uuid primary key default gen_random_uuid(),code varchar(80) not null unique,description text not null);
create table if not exists platform_api_keys(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),app_id uuid not null,name varchar(120) not null,key_prefix varchar(20) not null,key_hash char(64) not null unique,status varchar(20) not null check(status in('ACTIVE','REVOKED','EXPIRED')),expires_at timestamptz,revoked_at timestamptz,last_used_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,foreign key(tenant_id,app_id) references platform_external_apps(tenant_id,id));
create table if not exists platform_api_key_scopes(api_key_id uuid not null references platform_api_keys(id) on delete cascade,scope_id uuid not null references platform_api_scopes(id),primary key(api_key_id,scope_id));
create table if not exists platform_api_request_logs(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),app_id uuid not null,api_key_id uuid not null,method varchar(10) not null,path varchar(500) not null,status_code int not null,duration_ms int not null,requested_at timestamptz not null default now(),created_at timestamptz not null default now(),created_by uuid,updated_at timestamptz not null default now(),updated_by uuid,deleted_at timestamptz,foreign key(tenant_id,app_id) references platform_external_apps(tenant_id,id),foreign key(api_key_id) references platform_api_keys(id));
create table if not exists platform_webhook_subscriptions(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),app_id uuid not null,url varchar(2048) not null,events text[] not null,secret_hash char(64) not null,status varchar(20) not null check(status in('ACTIVE','INACTIVE','BLOCKED')),maximum_attempts int not null check(maximum_attempts between 1 and 10),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,foreign key(tenant_id,app_id) references platform_external_apps(tenant_id,id));
create table if not exists platform_webhook_events(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),event_type varchar(80) not null,entity_id uuid,payload jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_webhook_deliveries(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),subscription_id uuid not null references platform_webhook_subscriptions(id),event_id uuid not null references platform_webhook_events(id),attempt int not null check(attempt between 1 and 10),status varchar(20) not null check(status in('PENDING','DELIVERED','FAILED','ABANDONED')),http_status int,response_excerpt varchar(500),next_retry_at timestamptz,delivered_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_developer_docs(id uuid primary key,slug varchar(100) not null,title varchar(200) not null,culture varchar(5) not null check(culture in('pt-BR','en-US','es-ES')),content text not null,example_payload jsonb,sort_order int not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,unique(slug,culture));
create table if not exists platform_commercial_catalog(id uuid primary key,name varchar(100) not null,description text not null,monthly_price numeric(18,2) not null check(monthly_price>=0),annual_price numeric(18,2) not null check(annual_price>=0),user_limit int not null,property_limit int not null,integration_limit int not null,webhook_limit int not null,languages text[] not null,status varchar(20) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists platform_commercial_plan_features(id uuid primary key default gen_random_uuid(),catalog_id uuid not null references platform_commercial_catalog(id),feature_code varchar(100) not null,included boolean not null,limit_value int,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,unique(catalog_id,feature_code));
create table if not exists platform_integration_audit_events(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),category varchar(40) not null,action varchar(80) not null,entity_id uuid,actor_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
insert into platform_api_scopes(code,description) values ('properties.read','Leitura de propriedades'),('lots.read','Leitura de lotes'),('inventory.read','Leitura de estoque'),('orders.read','Leitura de pedidos'),('finance.managerial.read','Leitura financeira gerencial'),('documents.read','Leitura de documentos'),('evidence.write','Escrita de evidências'),('events.write','Escrita de eventos'),('webhooks','Gestão de webhooks'),('admin.restricted','Administração restrita') on conflict(code) do nothing;
create index if not exists ix_platform_modules_status on platform_marketplace_modules(status,featured);create index if not exists ix_platform_requests_tenant_status on platform_marketplace_requests(tenant_id,status,created_at desc);create index if not exists ix_platform_partner_access on platform_partner_tenant_access(tenant_id,partner_id,status,expires_at);create index if not exists ix_platform_apps_tenant_status on platform_external_apps(tenant_id,status);create index if not exists ix_platform_keys_tenant_status on platform_api_keys(tenant_id,status,expires_at);create index if not exists ix_platform_api_logs on platform_api_request_logs(tenant_id,requested_at desc);create index if not exists ix_platform_webhooks on platform_webhook_subscriptions(tenant_id,status);create index if not exists ix_platform_deliveries on platform_webhook_deliveries(tenant_id,status,next_retry_at);create index if not exists ix_platform_audit on platform_integration_audit_events(tenant_id,category,created_at desc);
do $$ declare n text; begin foreach n in array array['platform_tenant_modules','platform_marketplace_requests','platform_partner_tenant_access','platform_external_apps','platform_api_keys','platform_api_request_logs','platform_webhook_subscriptions','platform_webhook_events','platform_webhook_deliveries','platform_integration_audit_events'] loop execute format('alter table %I enable row level security',n);execute format('alter table %I force row level security',n);if not exists(select 1 from pg_policies where schemaname='public' and tablename=n and policyname=n||'_tenant') then execute format('create policy %I on %I using (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) with check (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',n||'_tenant',n);end if;end loop;end $$;
insert into platform.schema_versions(version,description) values('4.6.0','Sprint 46 - marketplace, parceiros, APIs e webhooks') on conflict(version) do nothing;
